#!/usr/bin/env node
/**
 * 把 shared/ 同步到小程序与每个云函数目录。
 * 云函数上传时只包含自身目录，因此必须持有副本；用 --check 在 CI 中防止副本漂移。
 */
import * as path from 'path';
import * as fs from 'fs';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, 'shared');
const TARGETS = [
  'src/shared',
  'cloudfunctions/game/shared',
  'cloudfunctions/getMiniProgramCode/shared',
];
const HEADER =
  '/* AUTO-GENERATED by scripts/sync-shared.mjs — 请勿直接编辑；修改根目录 shared/ 后重新同步 */\n';
const check = process.argv.includes('--check');
const files = fs.readdirSync(SRC).filter((f) => f.endsWith('.ts')).sort();

let bad = 0;
for (const target of TARGETS) {
  const dir = path.join(ROOT, target);
  fs.mkdirSync(dir, { recursive: true });
  for (const file of files) {
    const content = HEADER + fs.readFileSync(path.join(SRC, file), 'utf8');
    const dest = path.join(dir, file);
    const current = fs.existsSync(dest) ? fs.readFileSync(dest, 'utf8') : null;
    if (current === content) continue;
    if (check) {
      console.error(`[sync:shared] 副本不一致: ${target}/${file}`);
      bad++;
    } else {
      fs.writeFileSync(dest, content, 'utf8');
      console.log(`[sync:shared] 已同步 ${target}/${file}`);
    }
  }
}
if (check) {
  if (bad > 0) {
    console.error(`[sync:shared] 共 ${bad} 处不一致，请执行 npm run sync:shared`);
    process.exit(1);
  }
  console.log(`[sync:shared] 三处副本与 shared/ 一致（${files.length} 个文件）`);
}